package com.chainauth.blockchain;
import org.springframework.data.annotation.Id; import org.springframework.data.mongodb.core.index.Indexed; import org.springframework.data.mongodb.core.mapping.Document; import java.time.Instant;
@Document("identity_registry_events") public class IndexedChainEvent { @Id private String id; @Indexed(unique=true) private String eventKey; private long blockNumber; private String blockHash; private String transactionHash; private String rawLog; private Instant indexedAt=Instant.now(); public String getId(){return id;} public void setId(String v){id=v;} public String getEventKey(){return eventKey;} public void setEventKey(String v){eventKey=v;} public long getBlockNumber(){return blockNumber;} public void setBlockNumber(long v){blockNumber=v;} public String getBlockHash(){return blockHash;} public void setBlockHash(String v){blockHash=v;} public String getTransactionHash(){return transactionHash;} public void setTransactionHash(String v){transactionHash=v;} public String getRawLog(){return rawLog;} public void setRawLog(String v){rawLog=v;} public Instant getIndexedAt(){return indexedAt;} public void setIndexedAt(Instant v){indexedAt=v;} }
